import{_ as r,C as l,o as i,c as n,aj as c,E as o,j as d,a}from"./chunks/framework.DkvuVDKz.js";const m=JSON.parse('{"title":"Collapsible 折叠区域","description":"","frontmatter":{},"headers":[],"relativePath":"components/collapsible.md","filePath":"components/collapsible.md","lastUpdated":1789272501000}'),s={name:"components/collapsible.md"};function h(p,t,b,g,u,x){const e=l("XhDemo");return i(),n("div",null,[t[0]||(t[0]=c('<h1 id="collapsible-折叠区域" tabindex="-1">Collapsible 折叠区域 <a class="header-anchor" href="#collapsible-折叠区域" aria-label="Permalink to &quot;Collapsible 折叠区域&quot;">​</a></h1><p>一块可以展开收起的内容，只有一块。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/collapsible" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/collapsible.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/collapsible" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/collapsible" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/collapsible.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>不传 open 即为非受控，defaultOpen 只给初始值，之后由组件自己维护开合</p>',5)),o(e,{src:"collapsible/01-basic"}),t[1]||(t[1]=c('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;collapsible&quot;</code>：<code>root</code> · <code>header</code> · <code>trigger</code> · <strong><code>content</code></strong> · <code>indicator</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="受控" tabindex="-1">受控 <a class="header-anchor" href="#受控" aria-label="Permalink to &quot;受控&quot;">​</a></h3><p>传了 open 就由宿主说了算，组件自己不再改状态，只发 open-change 报告意图</p>',6)),o(e,{src:"collapsible/02-controlled"}),t[2]||(t[2]=d("h3",{id:"禁用",tabindex:"-1"},[a("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[3]||(t[3]=d("p",null,"disabled 把触发器整个关停，点击与键盘都不再改开合，已展开的内容维持原样",-1)),o(e,{src:"collapsible/03-disabled"}),t[4]||(t[4]=d("h3",{id:"尺寸",tabindex:"-1"},[a("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[5]||(t[5]=d("p",null,"size 换的是触发按钮的高度、内边距与字号，三档并排对照",-1)),o(e,{src:"collapsible/04-size"}),t[6]||(t[6]=d("h3",{id:"自定义展开标记",tabindex:"-1"},[a("自定义展开标记 "),d("a",{class:"header-anchor",href:"#自定义展开标记","aria-label":'Permalink to "自定义展开标记"'},"​")],-1)),t[7]||(t[7]=d("p",null,"往指示符部件里塞自己的图形，转向仍由皮肤按 open 接管",-1)),o(e,{src:"collapsible/05-marker"}),t[8]||(t[8]=d("h3",{id:"展开动画",tabindex:"-1"},[a("展开动画 "),d("a",{class:"header-anchor",href:"#展开动画","aria-label":'Permalink to "展开动画"'},"​")],-1)),t[9]||(t[9]=d("p",null,"收起时节点不卸载，作者接管内容区的 display，用一条行高过渡就能平滑展开",-1)),o(e,{src:"collapsible/06-transition"}),t[10]||(t[10]=d("h3",{id:"颜色",tabindex:"-1"},[a("颜色 "),d("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),t[11]||(t[11]=d("p",null,"tone 落在触发按钮的展开态上，六种语气各展开一份做对照",-1)),o(e,{src:"collapsible/07-tone"}),t[12]||(t[12]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>高级选项、补充说明这类默认不需要看见的单块内容。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>有好几块并列的可折叠内容：用<a href="./accordion">手风琴</a>，它管互斥与整组语义。</li><li>内容需要浮在页面之上：用<a href="./popover">气泡卡片</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>触发器与内容通过 <code>aria-controls</code> 与 <code>aria-expanded</code> 关联。</li><li>展开动画由皮肤给，内容高度由组件量出来。</li><li>指示符部件空着由皮肤画一枚箭头，塞进图形即以作者的为准，转向两种情形都由皮肤打。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>放进<a href="./card">卡片</a>、<a href="./form">表单</a>的高级选项区。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>触发器文字说明里面是什么，别只写&quot;展开&quot;。</li><li>收起时内容退出 Tab 序列，别让焦点落到看不见的地方。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>把必填字段藏进折叠区：用户提交失败也不知道错在哪。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-collapsible&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCollapsibleContent</code> <code>XhCollapsibleHeader</code> <code>XhCollapsibleIndicator</code> <code>XhCollapsibleRoot</code> <code>XhCollapsibleTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useCollapsible</code></td></tr><tr><td>状态机</td><td><code>collapsibleMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/collapsible.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultOpen</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，只作用于排版；作者没给就不写。</td></tr><tr><td><code>onOpenChange</code></td><td><code>(details: CollapsibleOpenChangeDetails) =&gt; void</code></td><td></td><td>open 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>open-change</code></td><td><code>CollapsibleOpenChangeDetails</code></td><td>open 状态变化；detail 为 <code>{ open: boolean }</code></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>header</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>open</code> · <code>closed</code></p><p><strong>事件</strong>：<code>OPEN</code> · <code>CLOSE</code> · <code>TOGGLE</code> · <code>CONTROLLED.OPEN</code> · <code>CONTROLLED.CLOSE</code></p><p><strong>判据</strong>：<code>isOpenControlled</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>open</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setOpen</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in trigger, not disabled</td><td>展开/收起 content</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/collapsible.css</code> 使用 <code>[data-scope=&quot;collapsible&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 与 <code>xihan.motion</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>header</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>header</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr><tr><td><code>indicator</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;open&#39; | &#39;closed&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-collapsible-content-fg</code></td><td><code>content</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>collapsible 的 content 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-content-py</code></td><td><code>*</code><br><code>content</code></td><td><code>padding-block</code></td><td><code>@keyframes xh-collapsible-collapse</code><br><code>@keyframes xh-collapsible-expand</code><br><code>default</code></td><td><code>--xh-stack-gap-md</code></td><td>collapsible 的 *、content 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-header-gap</code></td><td><code>header</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_collapsible-trigger-gap</code></td><td>collapsible 的 header 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-glyph-size-text</code></td><td>collapsible 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-bg</code></td><td><code>trigger</code></td><td><code>background</code></td><td><code>default</code></td><td><code>transparent</code></td><td>collapsible 的 trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-bg-hover</code></td><td><code>trigger</code></td><td><code>background</code></td><td><code>hover</code></td><td><code>--xh-bg-subtle</code></td><td>collapsible 的 trigger 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-fg</code></td><td><code>trigger</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>collapsible 的 trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-fg-open</code></td><td><code>trigger</code></td><td><code>color</code></td><td><code>state=open</code></td><td><code>--xh-_collapsible-open-fg</code></td><td>collapsible 的 trigger 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-font-size</code></td><td><code>trigger</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_collapsible-trigger-font-size</code></td><td>collapsible 的 trigger 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-font-weight</code></td><td><code>trigger</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>collapsible 的 trigger 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-gap</code></td><td><code>trigger</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-_collapsible-trigger-gap</code></td><td>collapsible 的 trigger 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-h</code></td><td><code>trigger</code></td><td><code>block-size</code></td><td><code>default</code></td><td><code>--xh-_collapsible-trigger-h</code></td><td>collapsible 的 trigger 部件 block-size 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-px</code></td><td><code>trigger</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_collapsible-trigger-px</code></td><td>collapsible 的 trigger 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-collapsible-trigger-radius</code></td><td><code>trigger</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-control</code></td><td>collapsible 的 trigger 部件 border-radius 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>关键帧 <code>xh-collapsible-collapse</code> · <code>xh-collapsible-expand</code> 随皮肤自带，不引用别处文件里的名字；<code>rotate</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>皮肤之外还有一段：退场由适配器的退场闸门把关，动画播完才真收起。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',53))])}const q=r(s,[["render",h]]);export{m as __pageData,q as default};
